export const MAP_W = 700;
export const MAP_H = 620;

const RAD = Math.PI / 180;
const N = 0.6028370046288244;
const C = 1.351221325417899;
const RHO0 = 1.5562263294996075;
const LON0 = -1.4660765716752369;
const SCALE = 1600.8852498041813;
const TX = 309.25578503998094;
const TY = 661.5133514523459;

/** Where a longitude and latitude (degrees) fall on the map, in viewBox units, to a tenth. */
export function project(lon: number, lat: number): { x: number; y: number } {
  const rho = Math.sqrt(C - 2 * N * Math.sin(lat * RAD)) / N;
  const theta = N * (lon * RAD - LON0);
  const x = rho * Math.sin(theta) * SCALE + TX;
  const y = -(RHO0 - rho * Math.cos(theta)) * SCALE + TY;
  return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10 };
}

